#include <bits/stdc++.h>
using namespace std;
int main(){
    int n;
    scanf("%d",&n);
    vector<int>p(n);
    for(int i=0;i<n;i++)scanf("%d",&p[i]);
    vector<pair<int,int>>ops;
    auto apply=[&](int x,int y){
        vector<int>np;
        for(int i=n-y;i<n;i++)np.push_back(p[i]);
        for(int i=x;i<n-y;i++)np.push_back(p[i]);
        for(int i=0;i<x;i++)np.push_back(p[i]);
        p=np;
        ops.push_back({x,y});
    };
    for(int t=0;t<n;t++){
        int pos=-1;
        for(int i=t;i<n;i++)if(p[i]==t+1){pos=i;break;}
        if(pos==t)continue;
        int rem=n-t;
        // work on subproblem p[t..n-1], but operations are global
        // brute force: try 1 op, then try 2 ops
        bool done=false;
        for(int x=1;x<n&&!done;x++)for(int y=1;x+y<=n&&!done;y++){
            int np;
            if(pos>=n-y)np=pos-(n-y);
            else if(pos>=x)np=y+(pos-x);
            else np=y+(n-y-x)+pos;
            if(np==t){apply(x,y);done=true;}
        }
        if(!done){// shouldn't happen for n>=3
        }
    }
    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops)printf("%d %d\n",x,y);
}
